import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"升","description":"周易集解 - 升","frontmatter":{"title":"升","description":"周易集解 - 升"},"headers":[],"relativePath":"zh/classics/jijie/046.md","filePath":"zh/classics/jijie/046.md"}'),l={name:"zh/classics/jijie/046.md"};function n(d,a,t,p,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="升" tabindex="-1">升 <a class="header-anchor" href="#升" aria-label="Permalink to “升”">​</a></h1><h2 id="升-1" tabindex="-1">升 <a class="header-anchor" href="#升-1" aria-label="Permalink to “升”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>升，元亨。用見大人，勿恤。南征吉。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：聚而上者謂之升，故受之以升也。</p><p>崔憬曰：用大牲而致孝享，故順天子而升為王矣，故言聚而上者謂之升也。</p><p>鄭玄曰：升，上也。坤地巽木，木生地中，日長而上，猶聖人在諸侯之中，明德日益高大也，故謂之升。升，進益之象矣。</p><p>虞翻曰：臨初之三，又有臨象；剛中而應，故元亨也。</p><p>虞翻曰：謂二當之五，為大人，離為見，坎為恤，二之五得正，故｢用見大人勿恤，有慶也｣。</p><p>虞翻曰：離，南方卦，二之五成離，故｢南征吉，志行也｣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：柔以時升，巽而順，剛中而應，是以大亨。用見大人勿恤，有慶也。南征吉，志行也。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>虞翻曰：柔謂五，坤也。升謂二。坤邑無君，二當升五虛，震兌為春秋，二升，坎離為冬夏。四時象正，故柔以時升也。</p><p>荀爽曰：謂二以剛居中，而來應五，故能大亨。上居尊位也。</p><p>荀爽曰：大人，天子，謂升居五，見為大人，群陰有主，無所復憂，而有慶也。</p><p>虞翻曰：二之五，坎為志。震為行。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：地中生木，升。君子以順德，積小以成高大。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：地謂坤。木謂巽。地中生木，以微至著，升之象也。</p><p>虞翻曰：君子謂三。小謂陽息復時。復小，為德之本。至二成臨。臨者，大也。臨初之三，巽為高。二之五，艮為順。坤為積，故順德積小成高大。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，允升，大吉。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>荀爽曰：謂一體相隨，允然俱升。初欲與巽一體，升居坤上，位尊得正，故大吉也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：允升大吉，上合志也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：謂初失正，乃與二陽允然合志，俱升五位，上合志也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，孚乃利用禴，無咎。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：禴，夏祭也。孚謂二，之五成坎，為孚；離為夏，故｢乃利用禴無咎｣矣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：九二之孚，有喜也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：升五得位，故有喜。</p><p>乾寶曰：剛中而應，故孚也。又言乃利用禴，於春時也。非時而祭曰禴。然則文王從儉以恤民，四時之祭，皆以禴禮。神享德與，信不求備也。故既濟九五曰：東鄰殺牛，不如西鄰之禴祭。實受其福。九五坎，坎為豕。然則禴祭以豕而已，不奢盈於禮，故曰有喜矣。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，升虛邑。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>荀爽曰：坤稱邑也。五虛無君，利二上居之，故曰｢升虛邑，無所疑也｣。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：升虛邑，無所疑也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：坎為疑，上得中，故無所疑也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，王用享於岐山，吉，無咎。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>荀爽曰：此本升卦也。巽升坤上，據三成艮。巽為歧，艮為山。王，謂五也。通有兩體，位正眾服，故吉也。四能與眾陰退避當升者，故無咎也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：王用享於岐山，順事也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：為順之初，在升當位。近比於五，乘剛於三。宜以進德，可修守。此象太王為狄所逼，徒居岐山之下，一年成邑，二年成都，三年五倍其初，通而王矣，故曰王用享於歧山。以其用通，避於狄難，順於時事，故吉無咎。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，貞吉，升階。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：二之五，故貞吉。巽為高，坤為土，震升高，故升階也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：貞吉升階，大得志也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：陰正居中，為陽作階，使升居五，已下降二，與陽相應，故吉而得志。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，冥升，利於不息之貞。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>荀爽曰：坤性暗昧，今升在上，故曰冥升也。陰用事，為消。陽用事，為息，陰正在上，陽道不息，陰之所利，故曰利於不息之貞。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：冥升在上，消不富也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：陰升失實，故消不富也。</p>',72)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
